.dashboard-page {
    box-sizing: border-box;
    min-height: 100vh;
    padding: var(--g-spacing-6);
    background: var(--g-color-base-background);
}

/* Leave room for the fixed ActionPanel at the bottom of the screen. */
.dashboard-page_editing {
    padding-bottom: calc(var(--g-spacing-10) * 3);
}

.dashboard-page__header {
    margin-bottom: var(--g-spacing-5);
}

.dashboard-page__empty {
    padding: var(--g-spacing-10) var(--g-spacing-4);
    text-align: center;
    border: 1px dashed var(--g-color-line-generic);
    border-radius: var(--g-border-radius-l);
}

@media (max-width: 767px) {
    .dashboard-page {
        padding: var(--g-spacing-4);
    }
}

/* Widget card fills its grid cell; overflowing content scrolls inside the card. */
.widget {
    box-sizing: border-box;
    display: flex;
    flex-direction: column;
    height: 100%;
    padding: var(--g-spacing-4);
    gap: var(--g-spacing-3);
    background: var(--g-color-base-float);
}

.widget__title {
    flex-shrink: 0;
}

.widget__body {
    flex: 1;
    min-height: 0;
    overflow: auto;
}

.widget__note {
    margin: 0;
    white-space: pre-wrap;
}

